-- Specs for the 74 catalog classics, and their notes in our own words.
--
-- 20261002033302_content_rights dropped the specs these drinks had copied
-- from Punch and Difford's Guide, but kept a "Spec adapted from Punch (url)"
-- line in the notes. So the classics (Negroni, Martini, Daiquiri...) showed a
-- citation and no recipe. This gives each one a house spec and drops the
-- citation, along with the sentences that quoted those sites.
--
-- Proportions are facts: a Negroni is equal parts whoever prints it. The
-- specs below are the common modern builds, with our own method and garnish,
-- and every ingredient is one already on the shared list.
--
-- Only touches a drink that still has no spec, and only rewrites notes that
-- still carry the citation, so an edit made since is kept and a re-run
-- changes nothing.

-- Seeded drinks don't queue automatic sketches.
SET "app.image_worker" = 'on';

CREATE TEMP TABLE "fix_drinks" ("name" text, "glass" text, "ice" text, "method" text, "notes" text);
CREATE TEMP TABLE "fix_lines" ("drink" text, "pos" int, "amount" numeric, "unit" text,
    "ingredient" text, "prep" text, "optional" boolean);

;

;

ALTER TABLE "fix_drinks" ADD COLUMN "item_id" uuid;
UPDATE "fix_drinks" f SET "item_id" = (
    SELECT i.id FROM "public"."items" i
    WHERE i.is_catalog AND i.item_type = 'cocktail' AND lower(i.name) = lower(f.name)
    ORDER BY i.created_at LIMIT 1
);

-- --- Notes: drop the citation (and, where given, the sentences quoting the site) ---

UPDATE "public"."items" i
SET "notes" = coalesce(f.notes, regexp_replace(i.notes, '\s*Spec (as )?adapted from [^\n]*$', ''))
FROM "fix_drinks" f
WHERE i.id = f.item_id
  AND i.notes ~ 'Spec (as )?adapted from';

-- --- Specs: only for drinks that have none ---

DELETE FROM "fix_drinks" f
WHERE f.item_id IS NULL
   OR EXISTS (SELECT 1 FROM "public"."recipes" r WHERE r.recipe_item_id = f.item_id);

-- Every name is on the shared list in production; a fresh database may lack
-- a brand or two, so add those (hidden from search, like the other seeds).
SELECT DISTINCT ON (public.ingredient_key(l.ingredient)) l.ingredient, 'ingredient', true
FROM "fix_lines" l
JOIN "fix_drinks" f ON f.name = l.drink
WHERE public.resolve_ingredient(l.ingredient) IS NULL;

                                "preparation_notes", "is_optional", "sort_order")
SELECT f.item_id, public.resolve_ingredient(l.ingredient), l.amount, l.unit, l.prep, l.optional, l.pos
FROM "fix_lines" l
JOIN "fix_drinks" f ON f.name = l.drink;

UPDATE "public"."items" i SET
    "glassware_id" = coalesce(i.glassware_id, (SELECT g.id FROM "public"."items" g WHERE g.item_type = 'glassware' AND g.bar_id IS NULL AND lower(g.name) = lower(f.glass) ORDER BY g.created_at LIMIT 1)),
    "ice_id" = coalesce(i.ice_id, (SELECT c.id FROM "public"."items" c WHERE c.item_type = 'ice' AND c.bar_id IS NULL AND lower(c.name) = lower(f.ice) ORDER BY c.created_at LIMIT 1))
FROM "fix_drinks" f
WHERE i.id = f.item_id;

SELECT f.item_id, m.id, 0
FROM "fix_drinks" f
CROSS JOIN LATERAL (
    SELECT x.id FROM "public"."items" x
    WHERE x.item_type = 'method' AND x.bar_id IS NULL AND lower(x.name) = lower(f.method)
    ORDER BY x.created_at LIMIT 1
) m
WHERE NOT EXISTS (SELECT 1 FROM "public"."item_methods" im WHERE im.item_id = f.item_id);

DROP TABLE "fix_drinks", "fix_lines";

RESET "app.image_worker";
